# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 2: CLASSROOM LIFE — SCHOOL SUBJECTS &amp; ROUTINES</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">SCHOOL SUBJECTS (DERSLER)</text>\n  <text x="40" y="92" font-size="11.5" fill="#1e3a8a">• Mathematics (Maths) — Matematik</text>\n  <text x="40" y="114" font-size="11.5" fill="#1e3a8a">• Physics / Chemistry / Biology — Fizik / Kimya / Biyoloji</text>\n  <text x="40" y="136" font-size="11.5" fill="#1e3a8a">• History / Geography — Tarih / Coğrafya</text>\n  <text x="40" y="158" font-size="11.5" fill="#1e3a8a">• Literature — Edebiyat</text>\n  <text x="40" y="180" font-size="11.5" fill="#1e3a8a">• Information Technology (IT) — Bilişim Teknolojileri</text>\n  <text x="40" y="202" font-size="11.5" fill="#1e3a8a">• Physical Education (PE) — Beden Eğitimi</text>\n  <text x="40" y="224" font-size="11.5" fill="#1e3a8a">• Visual Arts / Music — Görsel Sanatlar / Müzik</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">CLASSROOM ROUTINES &amp; STUDY HABITS</text>\n  <text x="370" y="92" font-size="11.5" fill="#14532d">• attend classes regularly (derslere düzenli katılmak)</text>\n  <text x="370" y="114" font-size="11.5" fill="#14532d">• take notes / revise for exams (not almak / sınava çalışmak)</text>\n  <text x="370" y="136" font-size="11.5" fill="#14532d">• hand in assignments on time (ödevleri zamanında teslim etmek)</text>\n  <text x="370" y="158" font-size="11.5" fill="#14532d">• do lab experiments / group projects (deney / grup projesi)</text>\n  <rect x="370" y="175" width="290" height="52" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="515" y="195" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Adverbs of Manner (Durum Zarfları - How?):</text>\n  <text x="515" y="214" text-anchor="middle" font-size="11" fill="#14532d">carefully, quietly, fluency → Irregular: good→well, fast→fast, hard→hard</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ADVERBS OF FREQUENCY (SIKLIK ZARFLARI VE CÜMLE DİZİLİMİ)</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">SIKLIK DERECESİ (HOW OFTEN?)</text>\n  <text x="42" y="92" font-size="12" font-weight="bold" fill="#78350f">100%  always (her zaman / daima)</text>\n  <text x="42" y="116" font-size="12" font-weight="bold" fill="#92400e">85%   usually / normally (genellikle)</text>\n  <text x="42" y="140" font-size="12" font-weight="bold" fill="#b45309">70%   often / frequently (sık sık)</text>\n  <text x="42" y="164" font-size="12" font-weight="bold" fill="#d97706">50%   sometimes / occasionally (bazen)</text>\n  <text x="42" y="188" font-size="12" font-weight="bold" fill="#ea580c">10%   rarely / seldom / hardly ever (nadiren)</text>\n  <text x="42" y="212" font-size="12" font-weight="bold" fill="#dc2626">0%    never (hiçbir zaman — olumlu fiille!)</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">CÜMLE İÇİNDEKİ KONUMU (WORD ORDER)</text>\n  <rect x="375" y="78" width="285" height="65" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="385" y="98" font-size="11.5" font-weight="bold" fill="#7e22ce">1. Ana Fiilden ÖNCE (Before Main Verb):</text>\n  <text x="385" y="116" font-size="11" fill="#581c87">• She usually revises her notes in the evening.</text>\n  <text x="385" y="132" font-size="11" fill="#581c87">• They never come to the classroom late.</text>\n  <rect x="375" y="152" width="285" height="75" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="385" y="172" font-size="11.5" font-weight="bold" fill="#7e22ce">2. \'To Be\' (am/is/are) Fiilinden SONRA:</text>\n  <text x="385" y="190" font-size="11" fill="#581c87">• He is always punctual for morning lessons.</text>\n  <text x="385" y="208" font-size="10.5" fill="#6b21a8">Zaman ifadeleri (once a week, every day) cümle sonuna gelir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PRESENT SIMPLE VS. PRESENT CONTINUOUS TENSE</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">PRESENT SIMPLE (GENİŞ ZAMAN)</text>\n  <text x="40" y="90" font-size="11.5" font-weight="bold" fill="#164e63">• Kullanım: Rutinler, alışkanlıklar, ders programı.</text>\n  <text x="40" y="112" font-size="11.5" fill="#155e75">• Yapı: V₁ / V-s(es)  |  don\'t / doesn\'t + V₁</text>\n  <text x="40" y="136" font-size="11.5" fill="#155e75">• Örnek: Ali studies Chemistry every Tuesday.</text>\n  <text x="40" y="156" font-size="11.5" fill="#155e75">• Örnek: Does she use digital apps? — Yes, she does.</text>\n  <rect x="40" y="172" width="285" height="54" rx="6" fill="#cffafe"/>\n  <text x="182" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Zaman İpuçları (Time Expressions):</text>\n  <text x="182" y="210" text-anchor="middle" font-size="10.5" fill="#164e63">every day, on Mondays, in the morning, always, usually</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">PRESENT CONTINUOUS (ŞİMDİKİ ZAMAN)</text>\n  <text x="370" y="90" font-size="11.5" font-weight="bold" fill="#881337">• Kullanım: Konuşma anında / geçici süren eylemler.</text>\n  <text x="370" y="112" font-size="11.5" fill="#9f1239">• Yapı: am / is / are + V-ing</text>\n  <text x="370" y="136" font-size="11.5" fill="#9f1239">• Örnek: Ali is doing a Physics experiment right now.</text>\n  <text x="370" y="156" font-size="11.5" fill="#9f1239">• Not: Stative verbs (know, like, understand, need, want)</text>\n  <text x="378" y="172" font-size="11" fill="#be123c">-ing almaz, Present Simple ile kullanılır!</text>\n  <rect x="370" y="182" width="290" height="46" rx="6" fill="#ffe4e6"/>\n  <text x="515" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Zaman İpuçları (Time Expressions):</text>\n  <text x="515" y="217" text-anchor="middle" font-size="10.5" fill="#881337">now, right now, at the moment, currently, today, this week</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
